T("Blizzard original", "暴雪原版")
T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "仇恨闪烁、渐进高亮和软目标图标由暴雪管理。可选颜色用于着色现有威胁材质；血条的威胁颜色仍在职责颜色覆盖层下方。软目标图标还需要启用姓名板图标开关，并在游戏中存在匹配的软目标。")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "光环图标及其更新由暴雪负责。为每种单位类型选择“保留暴雪设置”或“自定义”。增益、减益和控制效果可在预览中分别选中和拖动。光环大小使用暴雪自身的设置。")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "这些元素由暴雪负责。稀有度图标设置适用于所有姓名板；团队标记图标仅在敌方姓名板上隐藏。施法条细节控制暴雪自身的施法条。预览和实际姓名板使用相同的开关。")
