T("Blizzard supplies health and aura updates. List edits and preview work during combat; color pickers work after combat.", "暴雪提供生命值和光环更新。战斗中可编辑列表并预览；颜色选择在战斗结束后可用。")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "施法条的材质、颜色、进度和打断由暴雪提供。可在此自定义其文字和细节。在预览中选中并移动每个施法元素；位置在脱离战斗后生效。")
T("Blizzard supplies the icons. The Suite keeps its own button plates, bar frame and spacing. Native clicks, tooltips and notifications stay intact.", "图标由暴雪提供。Suite 保留自己的按钮底板、条框架和间距。原生点击、鼠标提示和通知保持不变。")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "名称和生命值由暴雪提供。Mapko请求完整敌方姓名板及两种生命值，使普通敌人也显示文字。宽度和高度只更改敌方血条的像素尺寸；0保留所选尺寸。预览中的背景、边框和职责填充是独立的实时皮肤层；右键点击某一层可打开对应设置。职责颜色使用已保存的调色板；法力仅作为施法者提示。可在此处的三点菜单或MSUF颜色中的姓名板页面更改调色板。")
