T("Blizzard's own cooldown swipe fills the ring: the global cooldown after each ability, and casts or channels while they run. A cast takes the place of the global cooldown until it ends; the bright edge marks how far the cast has come.", "暴雪自己的冷却扫过动画填充圆环：每个技能后的公共冷却，以及正在进行的施法或引导。施法期间会取代公共冷却直到结束；明亮的边缘标出施法进度。")
