T("Bubbles outside instances can take the MSUF look; Blizzard locks the ones inside instances. Each source keeps Blizzard's look or uses the MSUF one: the shared look or its own font, size, colors, spacing and width. A bubble is matched to the line it shows right after that line arrives. Turning bubbles off inside instances uses Blizzard's bubble settings and gives them back when you leave or turn it off.", "副本外的聊天气泡可以使用 MSUF 外观；副本内的气泡由暴雪锁定。每个来源可以保留暴雪外观，或使用 MSUF 外观：共用外观，或独立的字体、大小、颜色、间距和宽度。一条消息到达后，气泡会立即与其显示的文字对应。在副本内关闭气泡会使用暴雪的气泡设置，离开副本或关闭此选项时会恢复原设置。")
