T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "选择 MSUF 或 SharedMedia 字体和条材质。字体大小、描边、阴影、平滑/锐利/Slug 渲染、条高度和间距会立即更新 HUD。Slug 没有阴影。")
