T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "双击搜索结果以打开暴雪的申请窗口。启用双击提交后，第二次点击还会用该窗口中已选的职责直接申请；按住 Shift 则改为检查窗口。保存的备注可显示在窗口旁以便复制；结束编辑时才会保存。")
T("Double-click a search result to open Blizzard's normal application dialog.", "双击搜索结果可打开暴雪的正常申请对话框。")
T("Draft saved", "草稿已保存")
T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "拖动窗口顶边可移动窗口；拖动右下角可缩放。右上角的减号按钮可将兼容的窗口折叠为恢复标签。背包和受保护的窗口保持原生行为。")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "在 MSUF 编辑模式中拖动通告，或在此设置其时机、缩放和精确位置。")
T("Drag or use arrows to move; Shift: 5, Ctrl: 10.", "拖动或使用方向键移动；Shift：5，Ctrl：10。")
T("Drag or use arrows to move; click for settings.", "拖动或使用方向键移动；点击打开设置。")
T("Drag the bag title to move it; click for options.", "拖动背包标题可移动，点击可打开选项。")
T("Drag the bar's edge to move it on screen.", "拖动条的边缘可在屏幕上移动它。")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "材料包打开时拖动其标题即可单独移动。点击标题打开背包选项。在 MSUF 编辑模式中重置其位置，即可重新跟随暴雪的正常背包布局。")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "在MSUF编辑模式中拖动结果卡片，或在此设置屏幕锚点、宽度、缩放和位置。")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "拖动已打开背包的标题即可移动。点击标题打开背包选项。每个背包保留各自的位置。暴雪会在右侧显示你当前的金币；左侧可选的“本次”数值显示登录以来的变化，并在 /reload 后保留。可在此处或其 MSUF 编辑模式弹出窗口中调整合并背包的大小。在编辑模式中重置位置会让窗口回到暴雪的正常锚点。")
