T("Each response is its own switch and none acts in combat. A summon that skips a starting area, and a resurrection during a boss encounter or while Blizzard makes you wait, stay yours. Party invite declines never touch friends, Battle.net friends or guild members, and invites that ask for a role or start a quest session stay yours. A chat line can report each response.", "每种回应都有独立开关，战斗中均不执行。会跳过初始区域的召唤，以及首领战中或暴雪要求等待时的复活，均由你手动处理。不会拒绝好友、战网好友或公会成员的组队邀请；需要选择职责或开始任务同步会话的邀请也由你处理。可在聊天中提示每次回应。")
T("Each specialization keeps its own bar layout: positions, attachments, growth, rows, spacing and sizes. Until it has its own, it uses the current one.", "每个专精都会保留自己的条布局：位置、附着、增长方向、行数、间距和大小。尚无自己的布局时，使用当前布局。")
