T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "输入天赋或法术名称或ID，然后按回车。所有必需法术都必须已学会。留空可移除此条件。")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "输入天赋或法术名称或ID，然后按回车。只要已学会任一排除法术，就隐藏此条目。条件在脱离战斗时更新。")
