T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "对于术士，只在战斗中爆燃冲刺光环生效时显示提示。暴雪内置光环容器会跟随该光环；Suite 不扫描光环。MSUF 编辑模式可显示示例并移动提示。")
