T("Forever only. A secure fishing key that casts Fishing, equipping the rod you choose first, and a second key that applies the lure you choose. Set both under Keybindings > MSUF Suite. Each action needs your key press; interacting with the bobber stays manual. The optional sound profile sets your fishing volumes while you cast and restores them afterwards.", "仅限 Forever。安全钓鱼快捷键会先装备所选鱼竿，再施放钓鱼；另一快捷键用于使用所选鱼饵。请在按键设置 > MSUF Suite 中设置。每个操作都需亲自按键，与浮标交互仍需手动。可选音量配置会在施放钓鱼期间应用钓鱼音量，并在之后恢复。")
T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "仅限 Forever。学习并在此配置中保存完整飞行路线耗时。首次飞行不虚构预计时间。提前降落不会覆盖完整路线耗时。中途站点来自原生飞行地图，提示可预览路线。“在下一站降落”请求下一个可用降落点。")
T("Forever only. When a quest offers a choice of rewards, the one with the highest vendor value, counting its stack size, is marked. Nothing is selected or turned in for you.", "仅限 Forever。任务提供可选奖励时，会标记按堆叠数量计算后卖价最高的奖励。不会替你选择或交付任务。")
