T("Frames join aligned bars; detached bars keep separate frames. Effects are static. Threshold marks a fixed percentage. Preview switches apply live.", "外框连接生命条与施法条，没有可见施法时仅包围生命条。阴影和发光为静态效果。纹理保留生命和光环颜色。阈值线标记固定百分比，不是斩杀提醒。可在预览图层中分别开关各项功能。 位置分离或大小不同的条使用各自的边框。")
