T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Sort items by orders every Suite view; Name keeps the order each view has always had. Click a category header to hide or show its items. The footer counts free slots, and Mark items that beat what you wear puts a small arrow on equipment that beats what you wear in its slot. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "可保留暴雪网格，或选择 Suite 统一网格、按实体背包分组或分类。在背包窗口中使用“编辑分类”创建、重命名、排序或禁用分类；将物品拖到侧栏分类即可分配。“物品排序依据”影响所有 Suite 视图；“名称”保留各视图原有排序。点击分类标题可折叠或展开物品。底部显示空位数，“标记优于当前装备的物品”会在对应部位更好的装备上显示小箭头。背包较大时可滚动或使用“上一页/下一页”；战斗中同时显示全部格子。合并堆叠数量仅影响显示；在银行、公会银行、邮件、交易、拍卖行和商人处均恢复实体堆叠。")
