T("Lists carried gem types beside Blizzard's socket window. Inspect each gem with its normal bag tooltip and confirm compatibility in the native socket window before applying it.", "在暴雪宝石插槽窗口旁列出背包中的宝石种类。先通过正常的背包鼠标提示查看每颗宝石，再在游戏内置插槽窗口中确认是否兼容，然后再镶嵌。")
T("Lists the casts of attackable enemy nameplates while you are in a five-player dungeon, oldest first; the game runs each bar and timer. The game keeps spell, target, marker and interrupt details hidden from addons, so casts are never sorted or filtered by them: fading or hiding uses the game's important-spell flag (a hidden cast keeps its place in the list), raid markers sit on the spell icon, and the ready mark, an edge stripe or the whole bar, shows on interruptible casts while your interrupt is off cooldown. Dimming checks four times a second whether your interrupt reaches each listed enemy; a cast it cannot check stays bright. The interrupt is found from your talents and pet unless you enter a spell ID. MSUF Edit Mode shows sample casts for placing the list.", "在五人地下城中列出可攻击敌人姓名板上的施法，最早的在前；每条进度条和计时由游戏运行。游戏会对插件隐藏法术、目标、标记和能否打断，因此列表从不按这些信息排序或过滤：淡化或隐藏使用游戏的重要法术标记（隐藏的施法仍保留它在列表中的位置），团队标记显示在法术图标上，打断技能不在冷却时，可打断的施法会显示就绪标记（边缘色条或整条）。调暗功能每秒四次检查你的打断能否够到列表中的每个敌人；无法检查的施法保持明亮。除非你输入法术ID，否则根据你的天赋和宠物识别打断技能。MSUF 编辑模式会显示示例施法，便于放置列表。")
T("Lists the casts of enemy nameplates in five-player dungeons, oldest first, with timers the game runs.", "在五人地下城中列出敌方姓名板上的施法，最早的在前，计时由游戏运行。")
