T("MSUF stops only a log it started. A log that was already on stays on. Re-entering selected content cancels a pending stop. WoW writes the log in its Logs folder.", "MSUF 只会停止由它开始的记录。原本已开启的记录会保持开启。重新进入所选内容会取消待执行的停止。WoW 会将记录写入其 Logs 文件夹。")
