T("Observed enemies adds up the enemy forces of the living enemies in combat that you see as a nameplate or target, and the total they would bring. Enemies that give no forces count as zero; while the client keeps a value hidden, the line shows -- instead of a guess. Enemies out of sight are not counted.", "已观察的敌人会累加你通过姓名板或目标看到的、处于战斗中的存活敌人的敌方部队进度，并显示它们将带来的总计。不提供进度的敌人计为零；客户端隐藏某个数值时，该行显示 -- 而非估算。视野外的敌人不计入。")
