T("One combined bag with a clear Suite background and item levels on equipment. Keep Blizzard's own item grid, or choose a Suite view with pages, bag groups or categories. Using and sorting items stays Blizzard's.", "一个合并背包，带有清晰的 Suite 背景，并在装备上显示物品等级。可保留暴雪自带的物品网格，或选择带分页、按背包分组或分类的 Suite 视图。物品使用和整理仍由暴雪负责。")
