T("Only containers newly acquired after enabling this helper are opened. It waits for combat to end, opens one at a time, and leaves them to you while you hold Shift or a loot window or a window that gives item use another meaning is open: merchant, bank, guild bank, mail, trade, auction house, scrapper, socket, upgrade and similar. Warbound containers stay unopened unless you allow them; profiles that used this helper before keep opening them. Midnight Artisan payouts can wait while your Shard of Dundun is capped.", "只会打开启用此功能后新获得的容器。战斗结束后一次打开一个；按住 Shift，或拾取窗口或会改变物品使用含义的窗口（商人、银行、公会银行、邮件、交易、拍卖行、拆解机、宝石插槽、升级等）打开时，容器留给你手动处理。战团容器默认不打开，除非你允许；此前已使用此功能的配置会继续打开它们。钝顿碎片达到上限时，可以暂缓打开至暗之夜工匠报酬。")
T("Only in an active Delve and outside combat: if the player choice has exactly one enabled spell option, one button and no confirmation, MSUF selects it once. Other choices remain manual.", "仅在进行中的地下堡且脱离战斗时：如果玩家选择界面恰好只有一个可用法术选项、一个按钮且无需确认，MSUF 才会选择一次。其他选择仍需手动处理。")
