T("Opens your character window, on the tab you used last, when an item upgrade merchant opens. It closes only a window this helper opened and waits for the end of combat to open or close it.", "打开物品升级商人窗口时，以上次使用的标签页打开你的角色窗口。只会关闭由此功能打开的窗口；战斗中的打开或关闭会等到战斗结束。")
T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "可选用暴雪原有的聊天、地图、声音，以及低生命值或其他屏幕闪烁设置。关闭某个选项或整个功能时，MSUF 会恢复原值；功能运行期间你在暴雪设置中手动修改的值仍会保留。")
T("Optional artwork and spacing controls. Use MSUF Edit Mode for position, nudging, reset, undo and redo.", "可选的装饰图和间距控制。使用 MSUF 编辑模式进行定位、微调、重置、撤销和重做。")
