T("Remembers your characters that you visit while this helper is on and lists them beside the mail window. Click a name to fill the recipient, right-click to hide or restore it, and search by name. Only characters on your current or connected realms are listed. Sending stays manual.", "记录启用此辅助功能期间登录过的角色，并显示在邮件窗口旁。点击姓名可填写收件人，右键可隐藏或恢复，并支持按名称搜索。仅列出当前服务器或互通服务器的角色。发送仍需手动。")
