T("Reminders appear only outside combat. The advance setting also shows active buffs, food and weapon enchants when their remaining time reaches the chosen number of minutes; 0 shows only missing effects. A single scheduled wakeup handles the next threshold. Reminders hide in arenas and battlegrounds, where aura data can be restricted.", "提醒仅在脱离战斗时显示。提前提醒设置还会在生效中的增益、食物和武器附魔的剩余时间达到所选分钟数时显示它们；0 仅显示缺失的效果。只需一次计划唤醒即可处理下一个阈值。在竞技场和战场中提醒会隐藏，因为那里的光环数据可能受限。")
