T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "通报战斗中首次观察到的各队员死亡。可分别选择本地聊天、屏幕提示和声音。同时发生的死亡仅播放一次声音，也可包含自己的死亡。仅在组队且处于战斗时监听。")
