T("Restores this bar's default spells and buffs for your specialization. Other bars and specializations stay as they are. You can undo it.", "为你的专精恢复此条的默认法术和增益。其他条和专精保持不变。此操作可撤销。")
T("Restyles Blizzard's own buff and debuff buttons beside the minimap: icon size, icons per row, spacing, outline, text and where the block sits. Blizzard still owns the auras, their tooltips and right-click cancelling. The position and the debuff row offset are set here, not in Edit Mode. Each row's icon skin is chosen on the Icon Skins page.", "调整小地图旁暴雪增益和减益按钮的图标大小、每行数量、间距、轮廓、文字和位置。光环、提示及右键取消仍由暴雪管理。位置和减益行偏移在此设置，不在编辑模式中设置。各行的图标皮肤在图标皮肤页面选择。")
T("Result", "结果")
T("Results and details", "结果与详情")
T("Resurrection offers", "复活请求")
T("Retail Druids only. Every incoming whisper in combat is a possible Innervate cue; message text cannot be inspected reliably during chat lockdown. The alert waits for a publicly known Innervate cooldown, or shows a generic cue when readiness is unavailable. A preferred target can be outlined on an MSUF group frame resolved outside combat. MSUF Edit Mode previews the alert and edits its position and size.", "仅限正式服德鲁伊。战斗中收到的每条密语都可能是激活请求；聊天锁定期间无法可靠检查消息内容。提醒会等待公开可知的激活冷却，或在无法得知就绪状态时显示通用提示。首选目标可在脱离战斗时解析出的 MSUF 团队框体上添加轮廓。MSUF 编辑模式可预览提醒并编辑其位置和大小。")
T("Retail only. Shows while Skyriding is available, or only in flight if selected. Choose bars or Blizzard Vigor gems; gem scale and a refill sound are optional. Separate bar heights, Surge icon size and speed-value offsets are under Text and bars. MSUF Edit Mode previews the HUD. Unknown charge values display as dashes.", "仅限 Retail。在驭空术可用时显示，也可选择仅飞行时显示。可选进度条或暴雪精力宝石，宝石缩放与恢复音效可选。独立条高度、奔涌图标大小与速度数值偏移位于“文字与进度条”。MSUF 编辑模式可预览 HUD。未知充能数值显示为横线。")
