T("Silences the game sound files whose IDs you list, such as a mount or summon sound; up to 200. MSUF mutes exactly the files listed here and plays them again when you remove an ID or turn this helper off, and it leaves files muted by other addons alone. Muting works whether or not volume profiles are applied.", "静音列表中指定 ID 的游戏音效文件，例如坐骑或召唤音效，最多 200 个。MSUF 只静音所列文件，移除 ID 或关闭辅助功能后恢复播放，并保留其他插件设置的静音状态。无论是否应用音量配置，此功能都有效。")
T("Silences these game sound files, such as a mount or summon sound, while this helper is on. Remove an ID to hear that sound again.", "启用此辅助功能期间，静音这些游戏音效文件，例如坐骑或召唤音效。移除 ID 即可恢复该音效。")
