T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. The bank views have the same smart search, free slot count and collapsible category headers. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "使用银行窗口下方按钮切换原生分页、合并银行、合并战团银行和共享分类。共享分类包含可访问的角色与战团分页。“管理银行分页”返回暴雪的购买、存入与分页设置。银行视图同样支持智能搜索、空位统计和可折叠分类标题。每格保留原有物品操作，银行堆叠不会合并；点击战团物品会先切换至暴雪的战团银行分页，可退款物品存入战团银行前会请求确认。")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "在此分别开启或关闭动作条。重新开启时会恢复之前的显示模式。选择布局即可调整上方选中的动作条。")
T("Switch on the first option, then keep or drop the reminders you want. A reminder shows only when your character knows its spell. Stances, auras, shields, Shadowform and weapon or shield imbues show while they are missing. Buffs you put on an ally (Source of Magic, Blistering Scales, Earth Shield, Symbiotic Relationship) show while your buff is on nobody in the group; target an ally and click the icon to cast it. Right-click or middle-click any reminder to hide it until you reload the UI.", "启用第一个选项，再保留或关闭所需提醒。只有角色已学会相应法术时才会显示提醒。姿态、光环、护盾、暗影形态及武器或盾牌灌注会在缺失时显示。对盟友施加的增益（魔力之源、炽热之鳞、大地之盾、共生关系）会在队伍中无人拥有你的该增益时显示；选中盟友并点击图标即可施放。右键或中键点击任意提醒可将其隐藏，直到重新加载界面。")
T("Switch the whole Skinning module here, or adjust Blizzard and Suite windows separately below.", "在此开关整个皮肤模块，或在下方分别调整暴雪和 Suite 窗口。")
