T("The Durability, FPS and Latency places, and FPS / latency, take the warning color at these limits.", "耐久度、帧率、延迟信息块以及“帧率 / 延迟”会在达到这些阈值时采用警告颜色。")
T("The Glass material with MSUF Forever graphite, ivory and muted-gold colors.", "玻璃质感，搭配 MSUF Forever 的石墨色、象牙色和柔和金色。")
T("The Great Vault is available only in Retail", "宏伟宝库仅在正式服可用")
T("The Mapko skin for Blizzard nameplates. Blizzard keeps health, threat, casts, auras, selection and click handling.", "用于暴雪姓名板的Mapko皮肤。生命值、威胁、施法、光环、选择和点击处理仍由暴雪管理。")
T("The Suite Cooldown manager page (CDM) shows Blizzard's tracked cooldowns and buffs as bars you arrange and style freely.", "Suite 的冷却管理器（CDM）页面将暴雪追踪的冷却时间和增益显示为可自由排列和设置样式的计时条。")
T("The Suite Minimap page styles the minimap itself: size, shape, border, zoom, buttons and info texts. MSUF's own minimap icon is under Miscellaneous.", "Suite 的小地图页面可设置小地图本身的大小、形状、边框、缩放、按钮和信息文字。MSUF 自身的小地图图标位于“杂项”中。")
T("The Suite Nameplates page styles Blizzard's enemy and friendly nameplates. MSUF's aura filters only decide whether nameplate-only auras show on MSUF frames.", "Suite 的姓名板页面可设置暴雪敌方和友方姓名板的样式。MSUF 的光环过滤器仅决定是否在 MSUF 框架上显示仅限姓名板的光环。")
T("The Suite draws its own tracker and hides Blizzard's while it runs. Entries are sorted into groups: the focused quest, campaign and important quests, quests ready to hand in, regular quests, world quests, nearby bonus objectives, scenario and delve steps, zone event progress, tracked achievements and collectibles and, on Retail, tracked recipes, Traveler's Log activities and Housing endeavors. In a raid it can hide completely, only while a boss is engaged, or pause the regular list during any raid fight; the encounter view keeps running then. Quest symbols come as Suite letters or as Blizzard's icons, and the heading line can be switched off. The key binding Use tracked quest item uses the focused quest's item, else the first usable one, and picks a new item only outside combat. Left-click a group name to fold it or a quest to open its log entry; right-click for more actions.", "Suite 使用自己的追踪器，运行时隐藏暴雪追踪器。内容按焦点任务、战役和重要任务、可交付任务、普通任务、世界任务、附近奖励目标、场景战役与地下堡步骤、区域事件进度、已追踪成就与收藏品分组；在正式服还包括追踪的配方、旅行者日志活动及家宅事务。团队中可完全隐藏、仅首领交战时隐藏，或在任何团队战斗期间暂停常规列表；战斗视图仍继续运行。任务标记可使用 Suite 字母或暴雪图标，标题行可关闭。“使用追踪任务物品”快捷键会使用焦点任务物品，否则使用首个可用物品；仅在非战斗状态选择新物品。左键点击组名可折叠，点击任务可打开日志；右键显示更多操作。")
T("The Suite frames Blizzard's original Micro Buttons. Their artwork, clicks, tooltips, enabled states and notifications stay native. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "Suite 为暴雪原有的微型菜单按钮加上外框。其图形、点击、鼠标提示、启用状态和通知保持原生。队列和 FPS 指示器停留在暴雪编辑模式中的位置。不会运行任何周期性 MSKIN 更新。")
T("The Suite look gives Blizzard's dialogs a dark panel, and the Suite font sets their text font and size; each works alone, and without them dialogs keep Blizzard's look and fonts. A minimum height makes short dialogs taller once Blizzard has sized them; 0 keeps Blizzard's height. A custom position moves the first dialog and the ones Blizzard stacks below it; place it and set the height in MSUF Edit Mode.", "Suite外观为暴雪对话框提供深色面板，Suite字体设置其文字的字体和大小；两者都可单独使用，没有它们时对话框保持暴雪的外观和字体。最小高度会在暴雪确定大小后让较短的对话框变高；0保留暴雪的高度。自定义位置会移动第一个对话框及暴雪在其下方堆叠的对话框；在MSUF编辑模式中放置它并设置高度。")
T("The Suite skin engine is unavailable.", "Suite 皮肤引擎不可用。")
T("The WoW macro changed; import it again before replacing it", "WoW宏已更改，请重新导入后再替换")
T("The WoW macro is no longer available", "此WoW宏已不可用")
T("The action-bar glow also requires this buff on you. Clear the field to use only the original buff or stack condition.", "动作栏发光还要求你身上有此增益。清空此字段可仅使用原有增益或层数条件。")
T("The bank selection changed. Review the preview again.", "银行选择已更改。请重新检查预览。")
T("The chosen font could not be applied.", "无法应用所选字体。")
T("The chosen font was not found, so Blizzard text keeps its own font.", "找不到所选字体，暴雪文字将保留原字体。")
T("The chosen profile supplies all settings. Toggle which Suite modules are enabled in it.", "所选配置文件提供所有设置。可切换其中启用的 Suite 模块。")
T("The class buff is included only when your character knows it. Enter self-buff spell IDs separated by spaces or commas. For a consumable, enter item ID:aura ID; separate pairs with commas. Up to 12 total reminders are shown. Weapon enchant items use the main-hand or off-hand enchant state.", "仅当你的角色已学会职业增益时才会包括它。输入自身增益法术 ID，用空格或逗号分隔。消耗品请输入“物品 ID:光环 ID”；多组之间用逗号分隔。最多显示 12 个提醒。武器附魔物品使用主手或副手的附魔状态。")
T("The combined bag and reagent bag use a Suite panel with a distinct header, border, and accent line. Set background opacity to 0 for a transparent window; item slots stay visible.", "合并背包和材料包使用 Suite 面板，带有醒目的标题栏、边框和强调线。将背景不透明度设为 0 可得到透明窗口；物品栏位仍然可见。")
T("The combined bag setting is protected on this client", "此客户端上的合并背包设置受保护")
T("The configuration cannot be opened during combat.", "战斗中无法打开设置。")
T("The cooldown catalog is not available yet. Log in on this character and specialization, then open this page.", "冷却目录尚不可用。请使用此角色和专精登录，然后打开此页面。")
T("The cooldown manager is not loaded.", "冷却管理器未载入。")
T("The cooldown manager needs an update. Reload the interface.", "冷却管理器需要更新。请重载界面。")
T("The cooldown manager was reset: settings, spell lists and spell options.", "冷却管理器已重置：设置、法术列表和法术选项。")
T("The countdown turns to the warning color below this many seconds. All bars: the Text section's setting.", "倒计时低于此秒数时变为警告颜色。所有条：使用“文字”分区的设置。")
T("The dark sweep over the icon while it counts down.", "倒计时期间覆盖在图标上的暗色扫过效果。")
T("The default font follows MSUF Fonts while the default size follows Blizzard's chat size. Choose Blizzard chat font to keep its own face. Slug has no shadow.", "默认字体跟随 MSUF 字体，默认大小跟随暴雪聊天字号。选择“暴雪聊天字体”可保留其原有字形。Slug 没有阴影。")
T("The detailed character panel and stats are available only in Retail. WoW Forever keeps its own character layout.", "详细角色面板与属性仅在正式服可用。WoW Forever 保留自己的角色布局。")
T("The detailed character panel is available only in Retail.", "详细角色面板仅在正式服可用。")
T("The dungeon's timer", "地下城计时")
T("The engine remains dormant until a lifecycle event or an explicit user action requires work.", "在生命周期事件或用户明确操作需要处理之前，引擎保持休眠。")
T("The game could not use the chosen font, so Blizzard text keeps its own font.", "游戏无法使用所选字体，暴雪文字将保留原字体。")
T("The game has not sent the current season yet; until then every learned portal is listed.", "游戏尚未发送当前赛季；在此之前会显示所有已学会的传送。")
T("The global cooldown can leave the ring for a fixed circle of its own size and opacity, shown next to casts. Place it in MSUF Edit Mode; its button there works while this choice is on.", "公共冷却可以离开圆环，显示在一个有自己大小和不透明度的固定圆圈中，并与施法同时显示。在 MSUF 编辑模式中放置它；该选项开启时，那里的按钮才可用。")
T("The global name of a frame, for example ChatFrame1. The bar follows its place and size, never anchored to it. Until the frame exists, the bar stays put.", "框体的全局名称，例如 ChatFrame1。条形会跟随其位置和大小，但不直接锚定到该框体。框体出现前，条形保持原位。")
T("The header shows the meter and fight. Its buttons change the meter and fight directly in the window.", "标题栏显示统计类型和战斗。其按钮可直接在窗口中切换统计类型和战斗。")
T("The item changed. Review the preview again.", "物品已更改。请重新检查预览。")
T("The keystone notice remains local. The optional group announcement forwards only Blizzard's confirmed reset message immediately after your own reset request, while you are group leader. Failed attempts and resets by other players are not announced.", "钥石提示仍仅在本地显示。可选的队伍通报仅在你担任队长并亲自请求重置后，立即转发暴雪确认的重置消息。失败的尝试和其他玩家发起的重置不会通报。")
T("The level number takes the color Blizzard gives it on the target frame. Units you cannot attack keep white.", "等级数字采用暴雪目标框体的颜色。无法攻击的单位保持白色。")
T("The list of kept buttons is full.", "保留按钮列表已满。")
T("The macro draft is no longer available", "宏草稿已不可用")
T("The macro exceeds the 255-character limit", "宏超出 255 个字符的限制")
T("The macro library is full", "宏库已满")
T("The map grows or shrinks to the chosen width and height while the pointer is over it, then returns to its normal size. A circular map keeps its height equal to its width.", "鼠标指针位于地图上时，地图会放大或缩小到所选的宽度和高度，移开后恢复正常大小。圆形地图的高度始终等于宽度。")
T("The merchant's offers changed; nothing was bought.", "商人的商品已变化，未购买任何物品。")
T("The merchant's whole stock in one scrolling list with prices, quality colors and item levels.", "以一个可滚动列表显示商人的全部商品，包含价格、品质颜色和物品等级。")
T("The minutes below", "下方的分钟数")
T("The mouse wheel zooms the map. Middle-click runs the chosen action; left and right clicks keep working as usual.", "鼠标滚轮可缩放地图。中键点击执行所选操作；左键和右键点击照常使用。")
T("The native input box keeps autocomplete, links and chat commands.", "原生输入框保留自动补全、链接和聊天命令。")
T("The normal warning time", "正常提醒时间")
T("The optional glyph layer changes appearance while Blizzard keeps clicks, tooltips, enabled states and notifications. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "可选的符号层改变外观，点击、鼠标提示、启用状态和通知仍由暴雪保留。队列和 FPS 指示器停留在暴雪编辑模式中的位置。不会运行任何周期性 MSKIN 更新。")
T("The options module could not be loaded: %s", "无法加载选项模块：%s")
T("The options module did not finish initializing.", "选项模块未完成初始化。")
T("The party table grows in steps: characters with build and score, then the combat figures of Blizzard's damage meter, then the loot seen in chat. Each character keeps its latest runs; open the newest here or with /msufruns and step through older ones. Deleting a run asks for a second click. The card can wait until you close the chest's loot window.", "队伍表格按阶段扩展：带配置和评分的角色，然后是暴雪伤害统计的战斗数据，再然后是在聊天中看到的战利品。每个角色保存自己最近的挑战；在此处或使用 /msufruns 打开最新的一次，再翻看更早的记录。删除挑战需要再点击一次。卡片可以等到你关闭宝箱的战利品窗口后再显示。")
T("The preview and every section below edit this bar. Shared custom groups start with a separate list for explicit spell, aura and item IDs; disabling sharing restores the existing per-specialization list.", "预览及下方所有分区都编辑此条。共享自定义分组使用单独的明确法术、光环和物品ID列表；关闭共享后会恢复现有的各专精列表。")
T("The preview needs the cooldown manager.", "预览需要冷却管理器。")
T("The quick switch above remembers this mode when you turn the bar off. Choose Never to keep it hidden.", "关闭此条时，上方的快速开关会记住此模式。选择“从不”可保持隐藏。")
