T("Type /keys or /msufkeys to see your own current keystone. Add party, raid or instance to share it in that channel. /keys group requests keys from group members running this Suite helper. The /keys alias is used only when another addon has not claimed it. Inside dungeons and raids Blizzard locks chat for addons; your key is then shown only to you.", "输入 /keys 或 /msufkeys 查看自己当前的钥石。在命令后添加 party、raid 或 instance 可分享到对应频道。/keys group 会向同样运行此 Suite 功能的队友请求钥石信息。仅当其他插件未占用 /keys 时才启用此别名。在地下城和团队副本中暴雪会禁止插件发送聊天消息，此时钥石只显示给你自己。")
T("Type /msufguildprivacy or use the small ON/OFF button above the main chat window. Any chat window containing Guild or Officer is covered in full, including other channels in a mixed window. The guild chat in the Guild & Communities window can be covered as well; other communities stay visible. Reveal the chat again with the click chosen here. Messages keep arriving underneath.", "输入 /msufguildprivacy，或使用主聊天窗口上方的小型 ON/OFF 按钮。只要聊天窗口含有公会或官员频道，即使混有其他频道，也会遮住整个窗口。“公会与社区”窗口中的公会聊天也可以遮住，其他社区保持可见。使用此处选择的点击方式即可重新显示聊天；消息仍会在遮罩下继续接收。")
T("Type /msufraid to expand Blizzard's Raid Manager, /msufpull [1-60] for its native countdown, or /msufmark tank or /msufmark healer to mark one unambiguous party member. Optional automatic markers work only for one clear tank or healer in a five-player party, as leader or assistant. Existing and occupied markers are respected. Countdowns, markers and ready checks wait while Blizzard restricts them during combat, encounters and keystones; automatic markers try again afterwards.", "输入 /msufraid 展开暴雪团队管理器，输入 /msufpull [1-60] 使用其内置倒计时，或输入 /msufmark tank 或 /msufmark healer 为一名身份明确的队员添加标记。自动标记仅在五人队伍中恰好只有一名坦克或治疗者、且你是队长或助理时生效。现有及占用的标记不会被覆盖。战斗、首领战和钥石期间暴雪限制倒计时、标记和就位确认，这些操作会等待；自动标记会在之后再次尝试。")
T("Type /way x y for the current map or /way mapID x y. /msufway always works. The short /way alias is used only when no other addon owns it.", "输入 /way x y 可在当前地图设置路径点，也可输入 /way mapID x y 指定地图。/msufway 始终可用；只有其他插件未占用 /way 时，才会启用这个简写命令。")
