T("Uses Blizzard's Sell All Junk action when a merchant opens, including its per-bag exclusions. Hold Shift while opening the merchant to skip selling. The optional chat line confirms the request, not completed sales.", "打开商人时使用暴雪的“出售所有垃圾物品”操作，包括其按背包的排除设置。打开商人时按住 Shift 可跳过出售。可选的聊天提示只确认已发出请求，而非出售已完成。")
T("Uses MSUF's default spell lists for each specialization. Your own list changes are kept. This does not switch Suite profiles.", "为每个专精使用 MSUF 的默认法术列表。你自己的列表更改会保留。这不会切换 Suite 配置文件。")
