T("When BigWigs, Details or another addon provides LibKeystone or LibOpenRaid, a keys request asks it too, so players without the Suite are listed.", "当 BigWigs、Details 或其他插件提供 LibKeystone 或 LibOpenRaid 时，请求钥石信息也会向其查询，因此未安装 Suite 的玩家也会列出。")
T("When a dungeon queue pops", "地下城排队匹配成功时")
T("When a ready check starts outside combat and your mana as a healer is low, a short note shows how much you have; it turns red below half of your limit. Only your own mana is read.", "非战斗中开始就位确认且你作为治疗的法力不足时，会短暂提示你的剩余法力；低于你设定值的一半时变为红色。只会读取你自己的法力。")
T("When equipment sets exist, all equippable items are protected. Exact set membership is unavailable to this helper.", "存在装备方案时，所有可装备物品都会受到保护。此助手无法确定物品的具体方案归属。")
T("When leaving", "离开时")
T("When someone offers you a resurrection, its dialog gets a green frame, optionally with Blizzard's ready check sound, and its accept button can get a green frame of its own. Accepting stays your click.", "有人向你发出复活请求时，对话框会加上绿色边框，可选播放暴雪的就位确认音效，接受按钮也可以有自己的绿色边框。接受仍需你自己点击。")
T("When the key ends", "钥石结束时")
T("When the native group listing panel closes with applications still active, show their count in your own chat. Your applications remain active and no group chat is sent.", "关闭游戏内置队伍列表窗口时，如果仍有有效申请，就在你自己的聊天窗口显示申请数量。申请会保持有效，不会向队伍聊天发送消息。")
T("When the selected bar appears", "所选条的显示时机")
T("When this bar shows, and how far it fades out of combat. Tooltips show a spell when you hover its icon. This page and MSUF Edit Mode always show every bar.", "此条的显示时机，以及脱离战斗时淡出的程度。鼠标悬停在图标上时，鼠标提示会显示法术。此页面和 MSUF 编辑模式始终显示所有条。")
