T("Where the buff or debuff is looked for. Automatic: harmful spells on your target, all others on you.", "在何处查找增益或减益。自动：有害法术在你的目标身上查找，其他均在你身上查找。")
T("Where to show recent actions", "最近动作的显示位置")
T("Which Blizzard auras each kind of plate shows.", "每种姓名板显示哪些暴雪光环。")
T("Which number is drawn on top when both show.", "两者同时显示时，哪个数字绘制在上层。")
T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "显示哪些数字、哪个绘制在上层，以及它们的大小和位置。单个法术可单独设置：在预览中点击它们。下方的字体设置适用于所有条；Slug 没有阴影。")
T("Which units get nameplates and how plates share space.", "哪些单位显示姓名板，以及姓名板如何分配空间。")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "启用数据文本和此选项后，MSUF会在登录及金币变化时记录此角色的金币。将鼠标悬停在“金币”或“本次登录金币”数据文本上，可查看最后已知的账号总额及最多八个其他角色。不会执行后台扫描。")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "数据文字启用时，隐藏暴雪的行囊和背包栏位。点击“背包空间”数据文字可打开原生背包。关闭此项可恢复暴雪按钮。")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "钥石进行时，每个已击败的首领会显示你领先或落后多少：对比你在该首领上的最佳时间，或对比你最快完成挑战中的首领时间，可选当前钥石等级或任意等级。只计入此角色完成的挑战。开启目标时间后，仍存活的首领会显示需要超越的时间。")
T("While the buff of this item's use lasts, the icon shows its duration and stacks instead of the cooldown.", "此物品使用后的增益持续期间，图标显示增益持续时间与层数，而非冷却时间。")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "此法术的增益持续期间，图标显示其持续时间和层数，而非冷却。")
T("While this is on, move the window in MSUF Edit Mode or with the two positions below. While it is off, Blizzard's Edit Mode places it.", "启用时，可在 MSUF 编辑模式或通过下方两个位置设置移动窗口。关闭时，由暴雪编辑模式负责定位。")
