T("WoW Forever only. Lists your group's threat on the watched enemy from Blizzard's threat data, highest first; for a friendly target, its enemy is used. Values the game keeps hidden are left out. Turn the mouse wheel over the window when more members are listed than rows fit. The red mark shows where you would take aggro, which is not the point where you match the tank. The meter repaints at most five times a second and reads no combat log.", "仅限 WoW Forever。根据暴雪的威胁数据按从高到低列出队伍对所关注敌人的威胁；友方目标则使用其敌人。游戏隐藏的数值不显示。成员多于行数时，在窗口上滚动鼠标滚轮。红色标记表示你会拉到仇恨的位置，这与追平坦克的位置不同。计量器每秒最多刷新五次，不读取战斗记录。")
